$applications = $conn->query('SELECT * FROM applications ORDER BY id DESC');
$messages = $conn->query('SELECT * FROM contact_messages ORDER BY id DESC');
$applicationCount = (int) $conn->query('SELECT COUNT(*) AS total FROM applications')->fetch_assoc()['total'];
$messageCount = (int) $conn->query('SELECT COUNT(*) AS total FROM contact_messages')->fetch_assoc()['total'];
$todayApplications = (int) $conn->query('SELECT COUNT(*) AS total FROM applications WHERE DATE(created_at) = CURDATE()')->fetch_assoc()['total'];
$settings = $conn->query('SELECT * FROM site_settings WHERE id = 1')->fetch_assoc();
$saved = isset($_GET['saved']); $deleted = isset($_GET['deleted']);
$settingsErrors = $_SESSION['settings_errors'] ?? []; $oldSettings = $_SESSION['settings_old'] ?? [];
unset($_SESSION['settings_errors'], $_SESSION['settings_old']);
$formSettings = array_merge($settings, $oldSettings);
?>
